import React from 'react';

function Bar({ label, value, unit = '' }) {
  const pct = Math.round((value || 0) * 100);
  return (
    <div style={{ marginBottom:20 }}>
      <div style={{ display:'flex', justifyContent:'space-between', marginBottom:6 }}>
        <span style={{ fontSize:11, letterSpacing:'0.14em', textTransform:'uppercase', color:'rgba(10,10,10,0.45)' }}>{label}</span>
        <span style={{ fontSize:11, fontFamily:'monospace', color:'rgba(10,10,10,0.55)' }}>
          {typeof value === 'number' ? value.toFixed(2) : '—'}{unit}
        </span>
      </div>
      <div style={{ height:1, background:'rgba(10,10,10,0.1)' }}>
        <div style={{ height:1, background:'rgba(10,10,10,0.5)', width:`${pct}%`, transition:'width .5s cubic-bezier(0.16,1,0.3,1)' }} />
      </div>
    </div>
  );
}

export default function MetricDisplay({ metrics, typeProps }) {
  return (
    <div>
      <p style={{ fontSize:10, letterSpacing:'0.2em', textTransform:'uppercase', color:'rgba(10,10,10,0.35)', marginBottom:20 }}>
        Extracted — Silhouette
      </p>
      <Bar label="Drape"     value={metrics?.drape} />
      <Bar label="Curvature" value={metrics?.curvature} />
      <Bar label="Tension"   value={metrics?.tension} />
      <Bar label="Width"     value={metrics?.widthRatio} />
      <Bar label="Asymmetry" value={metrics?.asymmetry} />

      {typeProps && (
        <>
          <p style={{ fontSize:10, letterSpacing:'0.2em', textTransform:'uppercase', color:'rgba(10,10,10,0.35)', marginBottom:20, marginTop:28 }}>
            Mapped — Type Properties
          </p>
          <Bar label="Weight"  value={typeProps.weight / 900} />
          <Bar label="Stretch" value={typeProps.stretch / 140} />
          <Bar label="Spacing" value={(typeProps.spacing + 0.02) / 0.14} />
        </>
      )}
    </div>
  );
}
